export function translate(language: Language, key: string): string {
  return DICTIONARIES[language]?.[key] ?? DICTIONARIES.en[key] ?? key
}

const CURRENCY_LOCALES: Record<Currency, string> = { GBP: 'en-GB', USD: 'en-US', EUR: 'de-DE' }

export function formatCurrency(amount: number, currency: Currency): string {
  try {
    return new Intl.NumberFormat(CURRENCY_LOCALES[currency], { style: 'currency', currency, currencyDisplay: 'symbol', maximumFractionDigits: 0 }).format(amount)
  } catch {
    return `${currency} ${amount.toLocaleString()}`
  }
}